def process_string():
    string = input()
    a_end, b_end, c_end = 0, 0, 0

    # Find the end of the 'A' segment
    while a_end < len(string) and string[a_end] == 'A':
        a_end += 1

    # Find the end of the 'B' segment
    b_end = a_end
    while b_end < len(string) and string[b_end] == 'B':
        b_end += 1

    # Find the end of the 'C' segment
    c_end = b_end
    while c_end < len(string) and string[c_end] == 'C':
        c_end += 1

    # Check if the entire string has been traversed
    if c_end == len(string):
        print('Yes')
    else:
        print('No')
